-- T0-7: baseline at V116 for NEW customer databases (docs/2026-11-22-new-customer-database.md).
--
-- Generated by BaselineScriptGenerator from a database migrated through V1..V116, then reviewed.
-- Flyway applies it only to an empty database, and only when db/baseline is in its locations;
-- databases with migration history (OptimumSCS, dev, test) never run it. Migrations after V116
-- apply on top as usual.
--
-- The schema equals V1..V116 (BaselineSchemaIntegrationTests compares them); the data is only the
-- REQUIRED reference rows: no demo users, menu, stock or other seeds.
--
-- NEVER EDIT THIS FILE once a customer database has been built from it. Re-baseline by adding a new
-- B<N>__baseline.sql.


-- Tables ------------------------------------------------------------------------------------------

CREATE TABLE [account_payments] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [account_id] bigint NOT NULL,
    [amount] decimal(10, 2) NOT NULL,
    [note] nvarchar(255) NULL,
    [recorded_by] bigint NOT NULL,
    [created_at] datetime2(7) NOT NULL CONSTRAINT [DF_account_payments_created_at] DEFAULT (sysutcdatetime())
);
CREATE TABLE [accounts] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [name] nvarchar(100) NOT NULL,
    [contact_email] nvarchar(255) NULL,
    [active] bit NOT NULL CONSTRAINT [DF_accounts_active] DEFAULT ((1)),
    [department] nvarchar(100) NULL,
    [contact_number] nvarchar(20) NULL,
    [account_number] AS (CONVERT([nvarchar](24),'PM'+right('0000'+CONVERT([varchar](19),[id]),case when [id]>(9999) then len(CONVERT([varchar](19),[id])) else (4) end))) PERSISTED
);
CREATE TABLE [authorization_sessions] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [session_token] nvarchar(64) NOT NULL,
    [admin_id] bigint NOT NULL,
    [created_at] datetime2(7) NOT NULL CONSTRAINT [DF_authorization_sessions_created_at] DEFAULT (sysutcdatetime()),
    [expires_at] datetime2(7) NOT NULL
);
CREATE TABLE [authorization_tokens] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [token] nvarchar(64) NOT NULL,
    [admin_id] bigint NOT NULL,
    [created_at] datetime2(7) NOT NULL CONSTRAINT [DF_authorization_tokens_created_at] DEFAULT (sysutcdatetime()),
    [expires_at] datetime2(7) NOT NULL,
    [used] bit NOT NULL CONSTRAINT [DF_authorization_tokens_used] DEFAULT ((0))
);
CREATE TABLE [catalog_categories] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [parent_id] bigint NULL,
    [group_code] nvarchar(12) NOT NULL,
    [name] nvarchar(60) NOT NULL,
    [sort_order] int NOT NULL CONSTRAINT [DF_catalog_categories_sort_order] DEFAULT ((0)),
    [active] bit NOT NULL CONSTRAINT [DF_catalog_categories_active] DEFAULT ((1))
);
CREATE TABLE [component_catalog] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [name] nvarchar(50) NOT NULL,
    [extra_price] decimal(10, 2) NOT NULL,
    [active] bit NOT NULL CONSTRAINT [DF_component_catalog_active] DEFAULT ((1)),
    [category_id] bigint NULL
);
CREATE TABLE [component_categories] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [name] nvarchar(50) NOT NULL,
    [sort_order] int NOT NULL CONSTRAINT [DF_component_categories_sort_order] DEFAULT ((0)),
    [active] bit NOT NULL CONSTRAINT [DF_component_categories_active] DEFAULT ((1))
);
CREATE TABLE [count_sheet_categories] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [name] nvarchar(50) NOT NULL,
    [active] bit NOT NULL CONSTRAINT [DF_count_sheet_categories_active] DEFAULT ((1))
);
CREATE TABLE [daily_component_stock] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
