    [buffer_remaining] int NOT NULL,
    [status] nvarchar(25) NOT NULL CONSTRAINT [DF_daily_component_stock_status] DEFAULT ('PLANNED'),
    [actual_quantity] int NULL
);
CREATE TABLE [daily_meal_options] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [meal_period_id] bigint NULL,
    [meal_catalog_id] bigint NOT NULL,
    [option_date] date NOT NULL,
    [name] nvarchar(100) NOT NULL,
    [description] nvarchar(255) NULL,
    [price] decimal(10, 2) NOT NULL,
    [planned_portions] int NULL,
    [portions_remaining] int NULL,
    [status] nvarchar(25) NOT NULL CONSTRAINT [DF_daily_meal_options_status] DEFAULT ('PLANNED'),
    [actual_portions] int NULL
);
CREATE TABLE [day_close_overrides] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
