    [overridden_at] datetime2(7) NOT NULL CONSTRAINT [DF_day_close_overrides_at] DEFAULT (sysutcdatetime())
);
CREATE TABLE [device_credentials] (
    [id] uniqueidentifier NOT NULL CONSTRAINT [DF_device_credentials_id] DEFAULT (newid()),
