    [registered_by_name] nvarchar(255) NULL,
    [registered_at] datetime2(7) NOT NULL,
    [revoked_by] bigint NULL,
    [revoked_by_name] nvarchar(255) NULL,
    [revoked_at] datetime2(7) NULL,
    [revoke_reason] nvarchar(255) NULL,
    [till_code] nvarchar(10) NULL
);
CREATE TABLE [grv] (
    [id] bigint IDENTITY(1, 1) NOT NULL,
    [supplier_name] nvarchar(100) NOT NULL,
    [note] nvarchar(255) NULL,
    [received_by] bigint NOT NULL,
    [received_at] datetime2(7) NOT NULL CONSTRAINT [DF_grv_received_at] DEFAULT (sysutcdatetime()),
