    [source_id] bigint NOT NULL,
    [recorded_by] bigint NOT NULL,
    [created_at] datetime2(7) NOT NULL CONSTRAINT [DF_ingredient_stock_movements_created_at] DEFAULT (sysutcdatetime()),
