    [extras_adjusted] bit NOT NULL CONSTRAINT [DF_orders_extras_adjusted] DEFAULT ((0)),
    [card_reference] nvarchar(50) NULL,
    [pre_discount_total] decimal(10, 2) NOT NULL,
