    [reason] nvarchar(100) NOT NULL,
    [note] nvarchar(255) NULL,
    [recorded_by] bigint NOT NULL,
    [created_at] datetime2(7) NOT NULL CONSTRAINT [DF_waste_entries_created_at] DEFAULT (sysutcdatetime()),
