-- Check constraints -------------------------------------------------------------------------------

ALTER TABLE [account_payments] ADD CONSTRAINT [CK_account_payments_amount] CHECK ([amount]>(0));
ALTER TABLE [catalog_categories] ADD CONSTRAINT [CK_catalog_categories_group_code] CHECK ([group_code]='BEVERAGES' OR [group_code]='LIGHT_MEALS' OR [group_code]='SET_MEALS');
ALTER TABLE [daily_component_stock] ADD CONSTRAINT [CK_daily_component_stock_buffer_quantity_non_negative] CHECK ([buffer_quantity]>=(0));
ALTER TABLE [daily_component_stock] ADD CONSTRAINT [CK_daily_component_stock_buffer_remaining_non_negative] CHECK ([buffer_remaining]>=(0));
ALTER TABLE [daily_component_stock] ADD CONSTRAINT [CK_daily_component_stock_status] CHECK ([status]='READY' OR [status]='INGREDIENTS_REVIEWED' OR [status]='PLANNED');
ALTER TABLE [daily_meal_options] ADD CONSTRAINT [CK_daily_meal_options_planned_portions_non_negative] CHECK ([planned_portions]>=(0));
ALTER TABLE [daily_meal_options] ADD CONSTRAINT [CK_daily_meal_options_portions_remaining_non_negative] CHECK ([portions_remaining]>=(0));
ALTER TABLE [daily_meal_options] ADD CONSTRAINT [CK_daily_meal_options_status] CHECK ([status]='READY' OR [status]='INGREDIENTS_REVIEWED' OR [status]='PLANNED');
ALTER TABLE [device_credentials] ADD CONSTRAINT [CK_device_credentials_status] CHECK ([status]='REVOKED' OR [status]='ACTIVE');
ALTER TABLE [devices] ADD CONSTRAINT [CK_devices_status] CHECK ([status]='REVOKED' OR [status]='ACTIVE');
ALTER TABLE [devices] ADD CONSTRAINT [CK_devices_type] CHECK ([device_type]='POS');
ALTER TABLE [grv_lines] ADD CONSTRAINT [CK_grv_lines_quantity_received] CHECK ([quantity_received]>(0));
ALTER TABLE [grv_lines] ADD CONSTRAINT [CK_grv_lines_vat_code] CHECK ([vat_code]='NO_VAT' OR [vat_code]='ZERO_RATED' OR [vat_code]='STANDARD');
ALTER TABLE [ingredient_stock_movements] ADD CONSTRAINT [CK_ingredient_stock_movements_movement_type] CHECK ([movement_type]='CONSUMPTION_REVERSED' OR [movement_type]='STOCK_TAKE_ADJUSTMENT' OR [movement_type]='WASTED' OR [movement_type]='CONSUMED' OR [movement_type]='ISSUED' OR [movement_type]='RECEIVED');
ALTER TABLE [ingredient_stock_movements] ADD CONSTRAINT [CK_ingredient_stock_movements_source_type] CHECK ([source_type]='ORDER_LINE' OR [source_type]='STOCK_REQUEST' OR [source_type]='STOCK_TAKE' OR [source_type]='DIRECT_WASTE' OR [source_type]='DAILY_PLANNING_CONFIRMATION' OR [source_type]='GRV');
ALTER TABLE [ingredients] ADD CONSTRAINT [CK_ingredients_default_vat_code] CHECK ([default_vat_code]='NO_VAT' OR [default_vat_code]='ZERO_RATED' OR [default_vat_code]='STANDARD');
ALTER TABLE [ingredients] ADD CONSTRAINT [CK_ingredients_unit] CHECK ([unit]='PAIR' OR [unit]='BOX' OR [unit]='DOZEN' OR [unit]='PACK' OR [unit]='ROLL' OR [unit]='LOAF' OR [unit]='EACH' OR [unit]='LITRE' OR [unit]='KG');
ALTER TABLE [legacy_stock_takes] ADD CONSTRAINT [CK_stock_takes_counted_quantity] CHECK ([counted_quantity]>=(0));
ALTER TABLE [location_assignments] ADD CONSTRAINT [CK_location_assignments_role] CHECK ([role]='STATION_NONE' OR [role]='STATION_BAR' OR [role]='STATION_KITCHEN' OR [role]='PRODUCTION');
ALTER TABLE [location_changes] ADD CONSTRAINT [CK_location_changes_action] CHECK ([action]='ASSIGN' OR [action]='ACTIVATE' OR [action]='DEACTIVATE' OR [action]='UPDATE' OR [action]='CREATE');
ALTER TABLE [location_changes] ADD CONSTRAINT [CK_location_changes_before] CHECK (([action]='ASSIGN' OR [action]='CREATE') AND [old_name] IS NULL AND [old_sort_order] IS NULL AND [old_active] IS NULL OR NOT ([action]='ASSIGN' OR [action]='CREATE') AND [old_name] IS NOT NULL AND [old_sort_order] IS NOT NULL AND [old_active] IS NOT NULL);
ALTER TABLE [location_changes] ADD CONSTRAINT [CK_location_changes_role] CHECK ([action]='ASSIGN' AND [role] IS NOT NULL AND ([role]='STATION_NONE' OR [role]='STATION_BAR' OR [role]='STATION_KITCHEN' OR [role]='PRODUCTION') OR [action]<>'ASSIGN' AND [role] IS NULL AND [old_location_id] IS NULL);
ALTER TABLE [locations] ADD CONSTRAINT [CK_locations_kind] CHECK ([kind]='SECONDARY' OR [kind]='PRIMARY');
ALTER TABLE [locations] ADD CONSTRAINT [CK_locations_primary_active] CHECK ([kind]<>'PRIMARY' OR [active]=(1));
ALTER TABLE [login_attempts] ADD CONSTRAINT [CK_login_attempts_lock_level] CHECK ([lock_level]>=(1) AND [lock_level]<=(3));
ALTER TABLE [login_attempts] ADD CONSTRAINT [CK_login_attempts_method] CHECK ([method]='INVITE' OR [method]='CHANGE_PASSWORD' OR [method]='MANAGER_PIN' OR [method]='PIN' OR [method]='PASSWORD');
ALTER TABLE [login_attempts] ADD CONSTRAINT [CK_login_attempts_outcome] CHECK ([outcome]='DEMO_ACCOUNT' OR [outcome]='SHIFT_OPEN_ON_OTHER_TILL' OR [outcome]='TILL_LOCKED' OR [outcome]='DEVICE_NOT_REGISTERED' OR [outcome]='VALIDATION' OR [outcome]='RATE_LIMITED' OR [outcome]='LOCKED' OR [outcome]='DISABLED' OR [outcome]='UNKNOWN_USER' OR [outcome]='BAD_CREDENTIAL' OR [outcome]='SUCCESS');
ALTER TABLE [meal_catalog] ADD CONSTRAINT [CK_meal_catalog_low_stock_units] CHECK ([low_stock_units]>=(0) AND [low_stock_units]<=(10000));
ALTER TABLE [meal_catalog] ADD CONSTRAINT [CK_meal_catalog_station] CHECK ([station]='NONE' OR [station]='BAR' OR [station]='KITCHEN');
ALTER TABLE [meal_period_changes] ADD CONSTRAINT [CK_meal_period_changes_action] CHECK ([action]='ACTIVATE' OR [action]='DEACTIVATE' OR [action]='UPDATE' OR [action]='CREATE');
ALTER TABLE [meal_period_changes] ADD CONSTRAINT [CK_meal_period_changes_before] CHECK ([action]='CREATE' AND [old_name] IS NULL AND [old_sort_order] IS NULL AND [old_active] IS NULL OR [action]<>'CREATE' AND [old_name] IS NOT NULL AND [old_sort_order] IS NOT NULL AND [old_active] IS NOT NULL);
ALTER TABLE [meal_periods] ADD CONSTRAINT [CK_meal_periods_accepts] CHECK ([accepts]='LIGHT_MEALS' OR [accepts]='SET_MEALS');
ALTER TABLE [meal_periods] ADD CONSTRAINT [CK_meal_periods_times] CHECK ([all_day]=(1) AND [start_time] IS NULL AND [end_time] IS NULL OR [all_day]=(0) AND [start_time] IS NOT NULL AND [end_time] IS NOT NULL AND [start_time]<[end_time]);
ALTER TABLE [offline_grants] ADD CONSTRAINT [CK_offline_grants_expiry] CHECK ([expires_at]>[issued_at]);
ALTER TABLE [offline_grants] ADD CONSTRAINT [CK_offline_grants_revoke_reason] CHECK ([revoke_reason]='CASHIER_DEACTIVATED' OR [revoke_reason]='BROWSER_REVOKED' OR [revoke_reason]='TILL_REVOKED' OR [revoke_reason]='SHIFT_FORCE_CLOSED' OR [revoke_reason]='SHIFT_CLOSED' OR [revoke_reason]='REPLACED');
ALTER TABLE [offline_grants] ADD CONSTRAINT [CK_offline_grants_revoked] CHECK ([revoked_at] IS NULL AND [revoke_reason] IS NULL OR [revoked_at] IS NOT NULL AND [revoke_reason] IS NOT NULL);
ALTER TABLE [offline_sequences] ADD CONSTRAINT [CK_offline_sequences_seq] CHECK ([last_seq]>=(0));
ALTER TABLE [offline_till_pending] ADD CONSTRAINT [CK_offline_till_pending_count] CHECK ([pending_count]>=(1));
