-- Views -------------------------------------------------------------------------------------------

GO

-- B. What was offered: one row per plan entry. Meals from the daily meal options, extras from
-- the daily component stock. Every plan entry counts, whatever its status ("on the daily plan").
-- An item can appear more than once on a date; callers count DISTINCT plan_date.
CREATE   VIEW [v_offered_items] AS
SELECT
    'MEAL'                AS [item_type],
    [meal_catalog_id]     AS [catalog_id],
    [meal_period_id]      AS [meal_period_id],
    CAST(NULL AS NVARCHAR(50)) AS [plu_code],
    [option_date]         AS [plan_date]
FROM [daily_meal_options]
UNION ALL
SELECT
    'EXTRA',
    [component_catalog_id],
    [meal_period_id],
    CAST(NULL AS NVARCHAR(50)),
    [option_date]
FROM [daily_component_stock];
GO

-- Reports R1 §1.5: the definitions layer. Every report composes these views and never
-- re-derives a business rule, so each rule below is defined exactly once. Timestamps are
-- stored as UTC DATETIME2; the business calendar is Africa/Johannesburg (no daylight saving).
-- Each view exposes the shift's raw UTC opened_at so callers can filter a trading-day range
-- with a sargable predicate on the shifts(opened_at) index (V83).
-- Split across GO batches: CREATE VIEW must be the only statement in its batch.

-- Trading day of a shift = the Johannesburg calendar date of shifts.opened_at.
CREATE VIEW [v_shift_facts] AS
SELECT
    s.[id]                AS [shift_id],
    s.[cashier_id]        AS [owner_id],
    s.[status]            AS [status],
    s.[opening_float]     AS [opening_float],
    s.[opened_at]         AS [opened_at_utc],
    CAST((s.[opened_at] AT TIME ZONE 'UTC') AT TIME ZONE 'South Africa Standard Time' AS DATE) AS [trading_day]
FROM [shifts] s;
GO

-- One row per adjustment, attributed to the shift that processed it. Day processed = that
-- shift's trading day (the cash attribution used by shift reconciliation). Paid out:
-- refund_method CASH = cash paid out of the drawer; ACCOUNT_BALANCE = an account credit.
CREATE VIEW [v_adjustment_facts] AS
SELECT
    a.[id]                AS [adjustment_id],
    a.[order_id]          AS [order_id],
    a.[shift_id]          AS [processed_shift_id],
    sf.[opened_at_utc]    AS [processed_shift_opened_at_utc],
    sf.[trading_day]      AS [day_processed],
    a.[refund_method]     AS [refund_method],
    a.[amount]            AS [amount],
    CASE WHEN a.[refund_method] = 'CASH' THEN a.[amount] ELSE 0 END            AS [cash_paid_out],
    CASE WHEN a.[refund_method] = 'ACCOUNT_BALANCE' THEN a.[amount] ELSE 0 END AS [account_credits],
    CASE
        WHEN a.[action] = 'DISCOUNT' THEN 'DISCOUNT'
        WHEN a.[scope] = 'EXTRAS_ONLY' THEN 'EXTRAS_REMOVED'
        WHEN a.[action] = 'VOID' THEN 'VOID'
        ELSE 'REFUND'
    END                   AS [adjustment_type]
FROM [order_adjustments] a
JOIN [v_shift_facts] sf ON sf.[shift_id] = a.[shift_id];
GO

-- Complimentary meals: one row per complimentary order that wasn't voided, on its day of sale
-- (its shift's trading day) and in the shift it was rung in. value = the list value
-- (pre_discount_total). Outside the sales and net-sales figures.
CREATE   VIEW [v_complimentary_facts] AS
SELECT
    o.[id]                 AS [order_id],
    o.[shift_id]           AS [shift_id],
    sf.[opened_at_utc]     AS [shift_opened_at_utc],
    sf.[trading_day]       AS [day_of_sale],
    DATEPART(HOUR, (o.[created_at] AT TIME ZONE 'UTC') AT TIME ZONE 'South Africa Standard Time') AS [sale_hour],
    c.[reason_code]        AS [reason_code],
    o.[pre_discount_total] AS [list_value]
FROM [orders] o
JOIN [v_shift_facts] sf ON sf.[shift_id] = o.[shift_id]
LEFT JOIN [order_complimentaries] c ON c.[order_id] = o.[id]
WHERE o.[order_kind] = 'COMPLIMENTARY' AND o.[status] <> 'VOIDED';
GO

-- 5. Report views -------------------------------------------------------------------------------

-- As V92, except day_of_sale (booked_trading_day first) and sale_hour (sold_at first).
CREATE   VIEW [v_order_facts] AS
SELECT
    o.[id]                AS [order_id],
    o.[shift_id]          AS [shift_id],
    sf.[opened_at_utc]    AS [shift_opened_at_utc],
    COALESCE(o.[booked_trading_day], sf.[trading_day]) AS [day_of_sale],
    DATEPART(HOUR, (COALESCE(o.[sold_at], o.[created_at]) AT TIME ZONE 'UTC') AT TIME ZONE 'South Africa Standard Time') AS [sale_hour],
    CASE WHEN o.[status] IN ('VOIDED', 'REFUNDED') THEN 1 ELSE 0 END AS [is_voided_or_refunded],
    o.[pre_discount_total] AS [gross_sales],
    o.[sale_discount]      AS [discounts_at_sale],
    o.[total]              AS [order_total],
    COALESCE(adj.[voids], 0)              AS [voids],
    COALESCE(adj.[refunds], 0)            AS [refunds],
    COALESCE(adj.[extras_removed], 0)     AS [extras_removed],
    COALESCE(adj.[legacy_discounts], 0)   AS [legacy_discounts_after_payment],
    COALESCE(adj.[legacy_discount_count], 0) AS [legacy_discount_count],
    o.[pre_discount_total] - o.[sale_discount] - COALESCE(adj.[reductions], 0) AS [net_sales],
    COALESCE(pay.[cash], 0)           AS [cash_collected],
    COALESCE(pay.[card], 0)           AS [card_collected],
    COALESCE(pay.[account], 0)        AS [account_collected],
    COALESCE(pay.[collected], 0)      AS [collected],
    COALESCE(pay.[payment_lines], 0)  AS [payment_lines]
FROM [orders] o
JOIN [v_shift_facts] sf ON sf.[shift_id] = o.[shift_id]
OUTER APPLY (
    SELECT
        SUM(CASE WHEN a.[action] <> 'DISCOUNT' AND a.[scope] = 'WHOLE_ORDER' AND a.[action] = 'VOID'   THEN a.[amount] ELSE 0 END) AS [voids],
        SUM(CASE WHEN a.[action] <> 'DISCOUNT' AND a.[scope] = 'WHOLE_ORDER' AND a.[action] = 'REFUND' THEN a.[amount] ELSE 0 END) AS [refunds],
        SUM(CASE WHEN a.[action] <> 'DISCOUNT' AND a.[scope] = 'EXTRAS_ONLY' THEN a.[amount] ELSE 0 END) AS [extras_removed],
        SUM(CASE WHEN a.[action] = 'DISCOUNT' THEN a.[amount] ELSE 0 END) AS [legacy_discounts],
        SUM(CASE WHEN a.[action] = 'DISCOUNT' THEN 1 ELSE 0 END) AS [legacy_discount_count],
        SUM(a.[amount]) AS [reductions]
    FROM [order_adjustments] a
    WHERE a.[order_id] = o.[id]
) adj
OUTER APPLY (
    SELECT
        SUM(CASE WHEN p.[method] = 'CASH'    THEN p.[amount] ELSE 0 END) AS [cash],
        SUM(CASE WHEN p.[method] = 'CARD'    THEN p.[amount] ELSE 0 END) AS [card],
        SUM(CASE WHEN p.[method] = 'ACCOUNT' THEN p.[amount] ELSE 0 END) AS [account],
        SUM(p.[amount]) AS [collected],
        COUNT(*)        AS [payment_lines]
    FROM [order_payments] p
    WHERE p.[order_id] = o.[id]
) pay
WHERE o.[order_kind] = 'SALE';
GO

-- As V92, except trading_day (booked_trading_day first) and lines without a menu link, which keep
-- their own name (catalog_id and meal_period_id NULL).
CREATE   VIEW [v_order_line_facts] AS
SELECT
    'MEAL'                    AS [item_type],
    dmo.[meal_catalog_id]     AS [catalog_id],
    COALESCE(mc.[name], ol.[name]) AS [item_name],
    dmo.[meal_period_id]      AS [meal_period_id],
    CAST(NULL AS NVARCHAR(50)) AS [plu_code],
    o.[id]                    AS [order_id],
    sf.[shift_id]             AS [shift_id],
    sf.[opened_at_utc]        AS [shift_opened_at_utc],
    COALESCE(o.[booked_trading_day], sf.[trading_day]) AS [trading_day],
    ol.[quantity]             AS [quantity],
    ol.[unit_price]           AS [unit_price],
    ol.[unit_price] * ol.[quantity] AS [gross],
    CASE
        WHEN o.[order_kind] = 'COMPLIMENTARY' THEN 'COMPLIMENTARY'
        WHEN o.[status] = 'VOIDED' THEN 'VOIDED'
        WHEN o.[status] = 'REFUNDED' THEN 'REFUNDED_OR_REMOVED'
        ELSE 'NET'
    END                       AS [unit_bucket]
FROM [order_lines] ol
JOIN [orders] o              ON o.[id] = ol.[order_id]
JOIN [v_shift_facts] sf      ON sf.[shift_id] = o.[shift_id]
LEFT JOIN [daily_meal_options] dmo ON dmo.[id] = ol.[daily_meal_option_id]
LEFT JOIN [meal_catalog] mc       ON mc.[id] = dmo.[meal_catalog_id]
WHERE NOT (o.[order_kind] = 'COMPLIMENTARY' AND o.[status] = 'VOIDED')
UNION ALL
SELECT
    'EXTRA',
    dcs.[component_catalog_id],
    COALESCE(cc.[name], e.[component_name]),
    dcs.[meal_period_id],
    CAST(NULL AS NVARCHAR(50)),
    o.[id],
    sf.[shift_id],
    sf.[opened_at_utc],
    COALESCE(o.[booked_trading_day], sf.[trading_day]),
    e.[quantity],
    e.[price_delta],
    e.[price_delta] * e.[quantity],
    CASE
        WHEN o.[order_kind] = 'COMPLIMENTARY' THEN 'COMPLIMENTARY'
        WHEN o.[status] = 'VOIDED' THEN 'VOIDED'
        WHEN o.[status] = 'REFUNDED' OR e.[adjusted] = 1 THEN 'REFUNDED_OR_REMOVED'
        ELSE 'NET'
    END
FROM [order_line_extras] e
JOIN [order_lines] ol                 ON ol.[id] = e.[order_line_id]
JOIN [orders] o                       ON o.[id] = ol.[order_id]
JOIN [v_shift_facts] sf               ON sf.[shift_id] = o.[shift_id]
LEFT JOIN [daily_component_stock] dcs ON dcs.[id] = e.[daily_component_stock_id]
LEFT JOIN [component_catalog] cc      ON cc.[id] = dcs.[component_catalog_id]
WHERE NOT (o.[order_kind] = 'COMPLIMENTARY' AND o.[status] = 'VOIDED');
GO

-- C. Account movements: one row per movement, the same three terms the account screen's balance
-- uses (AccountService: charged − reversed − paid). Accounts carry no opening balance and no
-- credit limit, so the movements are the whole ledger.
--   CHARGE   an ACCOUNT payment on an order          entry_day = day of sale
--   CREDIT   an adjustment paid out ACCOUNT_BALANCE  entry_day = day processed
--            (voids, refunds, extras removed and legacy after-payment discounts alike)
--   PAYMENT  a settlement received (account_payments) entry_day = its Johannesburg date
-- entry_at_utc is the instant whose Johannesburg date is entry_day (the shift's opened_at for
-- CHARGE/CREDIT, the payment's own time for PAYMENT); occurred_at is when it actually happened.
-- Settlements have no method or reference column, so reference is "Payment #id" and the
-- description is the payment's note.
CREATE   VIEW [v_account_movements] AS
SELECT
    'CHARGE'              AS [movement_type],
    p.[id]                AS [source_id],
    p.[account_id]        AS [account_id],
    p.[amount]            AS [amount],
    sf.[trading_day]      AS [entry_day],
    sf.[opened_at_utc]    AS [entry_at_utc],
    o.[created_at]        AS [occurred_at],
    o.[id]                AS [order_id],
    CONCAT(N'Order #', o.[order_number]) AS [reference],
    CAST(N'Order paid on account' AS NVARCHAR(255)) AS [description]
FROM [order_payments] p
JOIN [orders] o          ON o.[id] = p.[order_id]
JOIN [v_shift_facts] sf  ON sf.[shift_id] = o.[shift_id]
WHERE p.[method] = 'ACCOUNT' AND p.[account_id] IS NOT NULL
UNION ALL
SELECT
    'CREDIT',
    a.[id],
    a.[account_id],
    a.[amount],
    af.[day_processed],
    af.[processed_shift_opened_at_utc],
    a.[created_at],
    o.[id],
    CONCAT(N'Order #', o.[order_number]),
    CAST(CASE af.[adjustment_type]
        WHEN 'VOID' THEN N'Order voided'
        WHEN 'REFUND' THEN N'Order refunded'
        WHEN 'EXTRAS_REMOVED' THEN N'Extras removed'
        ELSE N'Discount after payment (legacy)'
    END AS NVARCHAR(255))
FROM [order_adjustments] a
JOIN [v_adjustment_facts] af ON af.[adjustment_id] = a.[id]
JOIN [orders] o              ON o.[id] = a.[order_id]
WHERE a.[refund_method] = 'ACCOUNT_BALANCE' AND a.[account_id] IS NOT NULL
UNION ALL
SELECT
    'PAYMENT',
    ap.[id],
    ap.[account_id],
    ap.[amount],
    CAST((ap.[created_at] AT TIME ZONE 'UTC') AT TIME ZONE 'South Africa Standard Time' AS DATE),
    ap.[created_at],
    ap.[created_at],
    NULL,
    CONCAT(N'Payment #', ap.[id]),
    CAST(COALESCE(NULLIF(ap.[note], N''), N'Payment received') AS NVARCHAR(255))
FROM [account_payments] ap;
GO


