-- A Z reading is a fiscal record: once written it can't be changed or removed.
CREATE TRIGGER [trg_z_readings_insert_only] ON [z_readings]
AFTER UPDATE, DELETE
AS
BEGIN
    THROW 51000, 'Z readings are insert-only.', 1;
END;
GO
